183	(same-episode & 43 & 63.99 \\
184	leakage) & 44 & 55.43 \\
185	 & 45 & 56.14 \\
186	 & 46 & 55.45 \\
187	 & 47 & 50.08 \\
188	 & 48 & 48.03 \\
189	 & 49 & 59.30 \\
190	\cmidrule{2-3}
191	 & Mean$\pm$std & $54.1 \pm 5.4$ \\
192	\midrule
193	Episode-level & 42 & 48.1 \\
194	(held-out & 43 & 47.9 \\
195	episodes) & 44 & 49.6 \\
196	 & 45 & 49.4 \\
197	 & 46 & 48.5 \\
198	 & 47 & 43.1 \\
199	 & 48 & 45.4 \\
200	 & 49 & 44.8 \\
201	\cmidrule{2-3}
